package android.animation; public class Animator { public java.util.List<AnimatorListenerAdapter> listeners=new java.util.ArrayList<>(); public void addListener(AnimatorListenerAdapter l){listeners.add(l);} public void start(){} public void cancel(){for(AnimatorListenerAdapter l:listeners)l.onAnimationCancel(this);end();} public void end(){for(AnimatorListenerAdapter l:listeners)l.onAnimationEnd(this);} }
